with ch as (insert into chapters(subject_id,year,title,sort) values ('matematik',8,'Tal och procent',1) returning id), i0 as (insert into lessons(chapter_id,title,body,sort) select id,'Procent – grunderna','**Procent** betyder *hundradel*. 25 % är alltså 25/100 = 0,25.

### Tre vanliga frågor
1. **Delen:** Vad är 20 % av 150?  → 0,20 · 150 = **30**
2. **Andelen:** Hur många procent är 30 av 150? → 30/150 = 0,2 = **20 %**
3. **Det hela:** 30 är 20 % av vad? → 30 / 0,20 = **150**

### Förändringsfaktor
En höjning med 15 % motsvarar faktorn **1,15**. En sänkning med 15 % motsvarar **0,85**.
Exempel: 800 kr · 0,85 = 680 kr.

> Tips: Flera förändringar efter varandra multipliceras. +20 % och sedan −20 % ger 1,2 · 0,8 = 0,96, alltså 4 % *lägre* än från början.',1 from ch), i1 as (insert into lessons(chapter_id,title,body,sort) select id,'Bråk, decimaltal och procent','Samma tal kan skrivas på tre sätt:

| Bråk | Decimal | Procent |
|------|---------|---------|
| 1/2 | 0,5 | 50 % |
| 1/4 | 0,25 | 25 % |
| 3/4 | 0,75 | 75 % |
| 1/5 | 0,2 | 20 % |
| 1/3 | 0,333… | 33,3 % |

### Omvandla
- Bråk → decimal: dividera täljaren med nämnaren (3/4 = 3 ÷ 4 = 0,75).
- Decimal → procent: multiplicera med 100 (0,75 → 75 %).
- Procent → bråk: skriv över 100 och förkorta (40 % = 40/100 = 2/5).

### Förkorta och förlänga
12/16 kan förkortas med 4 till 3/4. Värdet ändras inte – bara skrivsättet.',2 from ch), i2 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'matematik',id,'easy','mcq','Vad är 25 % av 200?','["25", "50", "75", "100"]'::jsonb,'1'::jsonb,'25 % = en fjärdedel. 200 / 4 = 50.' from ch), i3 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'matematik',id,'easy','tf','3/4 är lika med 0,75.',null,'true'::jsonb,'3 ÷ 4 = 0,75, vilket är 75 %.' from ch), i4 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'matematik',id,'easy','numeric','Vad är 7 · 8?',null,'{"value": 56, "tol": 0}'::jsonb,'7 · 8 = 56.' from ch), i5 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'matematik',id,'easy','fill','Vad kallas ett heltal större än 1 som bara är delbart med 1 och sig självt?',null,'["primtal"]'::jsonb,'Exempel på primtal: 2, 3, 5, 7, 11, 13.' from ch), i6 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'matematik',id,'medium','numeric','Lös ekvationen 3x + 5 = 20. Vad är x?',null,'{"value": 5, "tol": 0}'::jsonb,'3x = 20 − 5 = 15, så x = 15/3 = 5.' from ch), i7 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'matematik',id,'medium','mcq','Ett par skor kostar 800 kr och priset sänks med 15 %. Vad blir det nya priset?','["120 kr", "680 kr", "720 kr", "650 kr"]'::jsonb,'1'::jsonb,'Förändringsfaktorn är 0,85. 800 · 0,85 = 680 kr.' from ch), i8 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'matematik',id,'medium','numeric','Vad är medelvärdet av talen 4, 8, 9 och 11?',null,'{"value": 8, "tol": 0}'::jsonb,'(4 + 8 + 9 + 11) / 4 = 32 / 4 = 8.' from ch), i9 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'matematik',id,'medium','tf','Arean av en triangel beräknas som basen gånger höjden delat med två.',null,'true'::jsonb,'A = (b · h) / 2.' from ch), i10 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'matematik',id,'hard','numeric','En cirkel har radien 5 cm. Hur stor är omkretsen i cm? (avrunda till heltal)',null,'{"value": 31, "tol": 1}'::jsonb,'O = 2 · π · r = 2 · 3,14 · 5 ≈ 31,4 cm.' from ch), i11 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'matematik',id,'hard','mcq','Ett pris höjs först med 20 % och sänks sedan med 20 %. Jämfört med startpriset är det nya priset…','["Samma", "4 % lägre", "4 % högre", "40 % lägre"]'::jsonb,'1'::jsonb,'1,20 · 0,80 = 0,96 → 4 % lägre än från början.' from ch), i12 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'matematik',id,'hard','numeric','Lös ekvationen 2(x − 3) = x + 4. Vad är x?',null,'{"value": 10, "tol": 0}'::jsonb,'2x − 6 = x + 4 → 2x − x = 4 + 6 → x = 10.' from ch), i13 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'matematik',id,'hard','match','Para ihop varje ekvation med sin lösning.','{"left": ["x² = 49", "2x = 18", "x / 4 = 3", "x − 7 = 1"], "right": ["x = 12", "x = 7", "x = 8", "x = 9"]}'::jsonb,'[1, 3, 0, 2]'::jsonb,'x² = 49 → x = 7 (positiv lösning), 2x = 18 → x = 9, x/4 = 3 → x = 12, x − 7 = 1 → x = 8.' from ch), i14 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'matematik',id,'expert','numeric','En rätvinklig triangel har kateterna 9 cm och 12 cm. Hur lång är hypotenusan i cm?',null,'{"value": 15, "tol": 0}'::jsonb,'Pythagoras sats: 9² + 12² = 81 + 144 = 225, √225 = 15.' from ch), i15 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'matematik',id,'expert','mcq','10 000 kr sätts in på ett konto med 5 % ränta per år (ränta på ränta). Hur mycket finns efter 2 år?','["11 000 kr", "11 025 kr", "10 500 kr", "12 000 kr"]'::jsonb,'1'::jsonb,'10 000 · 1,05² = 10 000 · 1,1025 = 11 025 kr.' from ch), i16 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'matematik',id,'expert','numeric','Ekvationssystemet x + y = 10 och x − y = 4. Vad är x?',null,'{"value": 7, "tol": 0}'::jsonb,'Addera ekvationerna: 2x = 14 → x = 7 (och y = 3).' from ch) insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'matematik',id,'expert','numeric','Hur många procent är 36 av 240?',null,'{"value": 15, "tol": 0}'::jsonb,'36 / 240 = 0,15 = 15 %.' from ch;
with ch as (insert into chapters(subject_id,year,title,sort) values ('matematik',8,'Algebra och ekvationer',2) returning id) insert into lessons(chapter_id,title,body,sort) select id,'Lösa ekvationer','En **ekvation** är en likhet med ett okänt tal, oftast kallat *x*.
Målet är att få *x* ensamt på ena sidan.

### Balansmetoden
Det du gör på ena sidan måste du göra på andra sidan.

```
3x + 5 = 20
3x     = 15      (−5 på båda sidor)
 x     = 5       (÷3 på båda sidor)
```

### Kontrollera
Sätt in svaret i ursprungsekvationen: 3 · 5 + 5 = 20 ✔

### Parenteser
Multiplicera in först: 2(x − 3) = 2x − 6.

### Vanliga fel
- Att glömma byta tecken när en term flyttas över.
- Att bara dela ena sidan med ett tal.',1 from ch;
with ch as (insert into chapters(subject_id,year,title,sort) values ('kemi',8,'Atomer och periodiska systemet',1) returning id), i0 as (insert into lessons(chapter_id,title,body,sort) select id,'Atomens byggnad','Allt runt omkring oss är uppbyggt av **atomer**. En atom består av:

- **Protoner** (+) i kärnan
- **Neutroner** (neutrala) i kärnan
- **Elektroner** (−) som rör sig runt kärnan i *elektronskal*

### Atomnummer och masstal
- **Atomnummer** = antalet protoner. Det bestämmer vilket grundämne det är. Kol har alltid 6 protoner.
- **Masstal** = protoner + neutroner. Klor med 17 protoner och 18 neutroner har masstalet 35.

### Isotoper
Atomer av samma grundämne med olika antal neutroner kallas isotoper (t.ex. kol-12 och kol-14).

### Joner
Om en atom tar upp eller lämnar ifrån sig elektroner blir den laddad – en **jon**. Na⁺ har lämnat en elektron, Cl⁻ har tagit upp en.',1 from ch), i1 as (insert into lessons(chapter_id,title,body,sort) select id,'Periodiska systemet','**Periodiska systemet** ordnar grundämnena efter atomnummer.

- **Perioder** (rader) visar antalet elektronskal.
- **Grupper** (kolumner) samlar ämnen med lika många elektroner i yttersta skalet – de har därför liknande egenskaper.

### Viktiga grupper
| Grupp | Namn | Exempel | Egenskap |
|-------|------|---------|----------|
| 1 | Alkalimetaller | Na, K | Mycket reaktiva |
| 17 | Halogener | F, Cl | Reaktiva icke-metaller |
| 18 | Ädelgaser | He, Ne, Ar | Reagerar nästan aldrig |

### Varför är ädelgaser så stabila?
Deras yttersta elektronskal är **fullt**. Andra atomer strävar efter samma sak – det kallas **oktettregeln** och förklarar varför atomer bildar bindningar.',2 from ch), i2 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'kemi',id,'easy','mcq','Vilken kemisk beteckning har vatten?','["H₂O", "CO₂", "O₂", "NaCl"]'::jsonb,'0'::jsonb,'Vatten består av två väteatomer och en syreatom: H₂O.' from ch), i3 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'kemi',id,'easy','tf','Guld har den kemiska beteckningen Au.',null,'true'::jsonb,'Au kommer från latinets *aurum*.' from ch), i4 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'kemi',id,'easy','fill','Vad kallas den minsta delen av ett grundämne som fortfarande har ämnets egenskaper?',null,'["atom", "en atom"]'::jsonb,'Ordet atom kommer från grekiskans *atomos* – odelbar.' from ch), i5 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'kemi',id,'easy','mcq','Vilken partikel i atomen har negativ laddning?','["Proton", "Neutron", "Elektron", "Jon"]'::jsonb,'2'::jsonb,'Elektronerna är negativa, protonerna positiva och neutronerna neutrala.' from ch), i6 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'kemi',id,'medium','mcq','En lösning med pH 7 är…','["Sur", "Basisk", "Neutral", "Starkt sur"]'::jsonb,'2'::jsonb,'pH under 7 är surt, över 7 basiskt och exakt 7 neutralt – som rent vatten.' from ch), i7 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'kemi',id,'medium','tf','Natriumklorid (NaCl) hålls ihop av kovalenta bindningar.',null,'false'::jsonb,'NaCl är ett salt med **jonbindning** mellan Na⁺ och Cl⁻.' from ch), i8 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'kemi',id,'medium','numeric','Kol har atomnummer 6. Hur många protoner har en kolatom?',null,'{"value": 6, "tol": 0}'::jsonb,'Atomnumret är alltid lika med antalet protoner.' from ch), i9 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'kemi',id,'medium','mcq','Vilken gas bildas när zink reagerar med saltsyra?','["Syrgas", "Vätgas", "Koldioxid", "Kvävgas"]'::jsonb,'1'::jsonb,'Zn + 2HCl → ZnCl₂ + H₂. Vätgasen kan testas med knallgasprovet.' from ch), i10 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'kemi',id,'hard','mcq','Balansera reaktionen: __ H₂ + O₂ → 2 H₂O. Vilken koefficient ska stå framför H₂?','["1", "2", "3", "4"]'::jsonb,'1'::jsonb,'2 H₂ + O₂ → 2 H₂O ger 4 H och 2 O på båda sidor.' from ch), i11 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'kemi',id,'hard','match','Para ihop bindningstypen med ett exempel.','{"left": ["Jonbindning", "Kovalent bindning", "Metallbindning"], "right": ["Koppar (Cu)", "Natriumklorid (NaCl)", "Vatten (H₂O)"]}'::jsonb,'[1, 2, 0]'::jsonb,'Salter har jonbindning, molekyler som vatten har kovalent bindning och metaller har metallbindning.' from ch), i12 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'kemi',id,'hard','fill','Vilket gruppnummer i periodiska systemet har ädelgaserna?',null,'["18", "grupp 18"]'::jsonb,'Ädelgaserna (He, Ne, Ar, Kr, Xe, Rn) står längst till höger i grupp 18.' from ch), i13 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'kemi',id,'hard','tf','En exoterm reaktion avger energi, oftast i form av värme.',null,'true'::jsonb,'Förbränning är ett typiskt exempel på en exoterm reaktion.' from ch), i14 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'kemi',id,'expert','mcq','En atom har 17 protoner och 18 neutroner. Vad är dess masstal?','["17", "18", "35", "36"]'::jsonb,'2'::jsonb,'Masstal = protoner + neutroner = 17 + 18 = 35 (klor-35).' from ch), i15 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'kemi',id,'expert','mcq','Varför är ädelgaserna så lite reaktiva?','["De har fullt yttre elektronskal", "De är tunga", "De saknar elektroner", "De är metaller"]'::jsonb,'0'::jsonb,'Ett fullt yttre skal är energimässigt stabilt – atomen behöver varken ta upp eller lämna elektroner.' from ch), i16 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'kemi',id,'expert','numeric','Vattens molmassa är 18 g/mol. Hur många mol är 36 g vatten?',null,'{"value": 2, "tol": 0}'::jsonb,'n = m / M = 36 / 18 = 2 mol.' from ch) insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'kemi',id,'expert','fill','Vad kallas reaktionen när en syra och en bas reagerar och bildar salt och vatten?',null,'["neutralisation", "neutralisering", "en neutralisation"]'::jsonb,'Exempel: HCl + NaOH → NaCl + H₂O.' from ch;
with ch as (insert into chapters(subject_id,year,title,sort) values ('kemi',8,'Kemiska reaktioner',2) returning id), i0 as (insert into lessons(chapter_id,title,body,sort) select id,'Kemiska bindningar','Atomer binder till varandra för att få fulla yttre elektronskal.

### Jonbindning
En metall **lämnar** elektroner till en icke-metall. Det bildas positiva och negativa **joner** som dras till varandra. Exempel: **NaCl** (koksalt). Salter har höga smältpunkter och leder ström när de är lösta i vatten.

### Kovalent bindning (molekylbindning)
Två icke-metaller **delar** på elektronpar. Exempel: **H₂O**, **CO₂**, **O₂**. Molekyler har ofta låga smält- och kokpunkter.

### Metallbindning
Metallatomer delar ett "hav" av fria elektroner. Därför leder metaller ström och värme och går att böja.

### Snabbtest
- Metall + icke-metall → jonbindning
- Icke-metall + icke-metall → kovalent bindning
- Metall + metall → metallbindning',1 from ch) insert into lessons(chapter_id,title,body,sort) select id,'Syror och baser','### pH-skalan
pH går från 0 till 14.
- **pH < 7** surt (citron ≈ 2, magsaft ≈ 1,5)
- **pH = 7** neutralt (rent vatten)
- **pH > 7** basiskt (tvål ≈ 10, lut ≈ 14)

### Vad är en syra?
En syra avger **vätejoner (H⁺)** i vatten. Vanliga syror: saltsyra HCl, svavelsyra H₂SO₄, kolsyra H₂CO₃.

### Vad är en bas?
En bas tar upp H⁺ eller avger **hydroxidjoner (OH⁻)**. Vanliga baser: natriumhydroxid NaOH, ammoniak NH₃.

### Neutralisation
Syra + bas → **salt + vatten**.
HCl + NaOH → NaCl + H₂O

### Indikatorer
BTB är gul i sur lösning, grön i neutral och blå i basisk.',2 from ch;
with ch as (insert into chapters(subject_id,year,title,sort) values ('fysik',8,'Kraft och rörelse',1) returning id), i0 as (insert into lessons(chapter_id,title,body,sort) select id,'Hastighet och acceleration','### Hastighet
Hastighet = sträcka / tid, **v = s / t**.
Enheten är m/s eller km/h. 1 m/s = 3,6 km/h.

Exempel: 120 km på 2 h → 60 km/h.

### Acceleration
Acceleration är hur snabbt hastigheten ändras: **a = Δv / t** (enhet m/s²).
Ett föremål som faller fritt accelererar med ungefär **9,8 m/s²** (ofta avrundat till 10).
Efter 3 sekunder: v = 10 · 3 = 30 m/s.

### Diagram
I ett **s–t-diagram** betyder brant linje hög hastighet.
I ett **v–t-diagram** betyder brant linje stor acceleration, och arean under kurvan är sträckan.',1 from ch), i1 as (insert into lessons(chapter_id,title,body,sort) select id,'Newtons lagar','### Första lagen – tröghetslagen
Ett föremål behåller sin rörelse (eller vila) tills en kraft påverkar det. Det är därför du åker framåt när bussen bromsar.

### Andra lagen – kraftekvationen
**F = m · a**
Kraft (N) = massa (kg) · acceleration (m/s²).
5 kg som accelererar 3 m/s² kräver 15 N.

### Tredje lagen – kraft och motkraft
Varje kraft har en lika stor motriktad kraft. När du hoppar trycker du på jorden – och jorden trycker tillbaka.

### Tyngdkraft
Tyngd = m · g, där g ≈ 9,8 N/kg. En massa på 2 kg har tyngden ≈ 19,6 N.',2 from ch), i2 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'fysik',id,'easy','mcq','Vilken är SI-enheten för kraft?','["Joule", "Newton", "Watt", "Volt"]'::jsonb,'1'::jsonb,'Kraft mäts i newton (N), uppkallad efter Isaac Newton.' from ch), i3 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'fysik',id,'easy','tf','Ljud färdas snabbare än ljus.',null,'false'::jsonb,'Ljus färdas ca 300 000 km/s, ljud bara ca 340 m/s i luft.' from ch), i4 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'fysik',id,'easy','numeric','En bil kör 120 km på 2 timmar. Vad är medelhastigheten i km/h?',null,'{"value": 60, "tol": 0}'::jsonb,'v = s / t = 120 / 2 = 60 km/h.' from ch), i5 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'fysik',id,'easy','fill','Vad kallas kraften som drar föremål mot jorden?',null,'["gravitation", "tyngdkraft", "gravitationskraft", "tyngdkraften", "gravitationen"]'::jsonb,'Tyngdkraften (gravitationen) verkar mellan alla massor.' from ch), i6 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'fysik',id,'medium','numeric','Ohms lag: Spänningen är 12 V och resistansen 4 Ω. Hur stor är strömmen i ampere?',null,'{"value": 3, "tol": 0}'::jsonb,'I = U / R = 12 / 4 = 3 A.' from ch), i7 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'fysik',id,'medium','mcq','Vilken av dessa är en förnybar energikälla?','["Kol", "Olja", "Vindkraft", "Naturgas"]'::jsonb,'2'::jsonb,'Vind, sol, vatten och biobränsle är förnybara – de tar inte slut.' from ch), i8 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'fysik',id,'medium','tf','Ljusets hastighet i vakuum är ungefär 300 000 km/s.',null,'true'::jsonb,'Exakt värde: 299 792 458 m/s.' from ch), i9 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'fysik',id,'medium','mcq','Newtons första lag handlar om…','["Tröghet", "Kraft = massa · acceleration", "Kraft och motkraft", "Gravitation"]'::jsonb,'0'::jsonb,'Första lagen kallas tröghetslagen.' from ch), i10 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'fysik',id,'hard','numeric','F = m · a. En massa på 5 kg accelererar med 3 m/s². Hur stor är kraften i newton?',null,'{"value": 15, "tol": 0}'::jsonb,'F = 5 · 3 = 15 N.' from ch), i11 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'fysik',id,'hard','numeric','En lampa drar 2 A vid 230 V. Vilken effekt har den i watt?',null,'{"value": 460, "tol": 0}'::jsonb,'P = U · I = 230 · 2 = 460 W.' from ch), i12 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'fysik',id,'hard','mcq','Varför ser vi blixten innan vi hör åskan?','["Ljus färdas mycket snabbare än ljud", "Ljud färdas snabbare än ljus", "Blixten uppstår före åskan", "Åskan sker längre bort"]'::jsonb,'0'::jsonb,'Ljuset når oss nästan omedelbart; ljudet tar ca 3 s per kilometer.' from ch), i13 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'fysik',id,'hard','match','Para ihop storheten med rätt enhet.','{"left": ["Energi", "Effekt", "Spänning", "Resistans"], "right": ["Ohm", "Watt", "Joule", "Volt"]}'::jsonb,'[2, 1, 3, 0]'::jsonb,'Energi i joule, effekt i watt, spänning i volt, resistans i ohm.' from ch), i14 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'fysik',id,'expert','numeric','Ett föremål faller fritt från vila (g ≈ 10 m/s²). Vilken hastighet i m/s har det efter 3 sekunder? (bortse från luftmotstånd)',null,'{"value": 30, "tol": 0}'::jsonb,'v = g · t = 10 · 3 = 30 m/s.' from ch), i15 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'fysik',id,'expert','numeric','Lägesenergi: E = m · g · h. m = 2 kg, h = 5 m, g = 9,8. Hur många joule? (heltal)',null,'{"value": 98, "tol": 1}'::jsonb,'E = 2 · 9,8 · 5 = 98 J.' from ch), i16 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'fysik',id,'expert','mcq','Två motstånd på 6 Ω och 3 Ω parallellkopplas. Vad blir ersättningsresistansen?','["9 Ω", "4,5 Ω", "2 Ω", "1 Ω"]'::jsonb,'2'::jsonb,'1/R = 1/6 + 1/3 = 1/6 + 2/6 = 3/6 → R = 2 Ω.' from ch) insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'fysik',id,'expert','mcq','Vilket påstående om trycket i en vätska stämmer?','["Det ökar med djupet", "Det minskar med djupet", "Det är konstant", "Det beror bara på kärlets form"]'::jsonb,'0'::jsonb,'p = ρ · g · h – ju djupare, desto större tryck.' from ch;
with ch as (insert into chapters(subject_id,year,title,sort) values ('fysik',9,'Elektricitet',2) returning id) insert into lessons(chapter_id,title,body,sort) select id,'Ohms lag','### Tre storheter
- **Spänning U** (volt, V) – "trycket" som driver strömmen
- **Ström I** (ampere, A) – hur många laddningar som passerar per sekund
- **Resistans R** (ohm, Ω) – motståndet mot strömmen

### Ohms lag
**U = R · I**, alltså I = U / R och R = U / I.

Exempel: 12 V över 4 Ω ger I = 12 / 4 = 3 A.

### Effekt
**P = U · I** (watt). En lampa på 230 V som drar 2 A har effekten 460 W.

### Serie- och parallellkoppling
- **Serie:** samma ström överallt, resistanserna adderas (R = R₁ + R₂).
- **Parallell:** samma spänning över grenarna, 1/R = 1/R₁ + 1/R₂. Ersättningsresistansen blir *mindre* än den minsta.',1 from ch;
with ch as (insert into chapters(subject_id,year,title,sort) values ('biologi',8,'Cellen och genetik',1) returning id), i0 as (insert into lessons(chapter_id,title,body,sort) select id,'Cellen','Alla levande organismer är uppbyggda av **celler**.

### Delar i en djurcell
- **Cellmembran** – styr vad som kommer in och ut
- **Cellkärna** – innehåller DNA
- **Mitokondrier** – cellens "kraftverk", frigör energi ur socker (cellandning)
- **Ribosomer** – bygger proteiner

### Växtcellen har dessutom
- **Cellvägg** av cellulosa
- **Kloroplaster** med klorofyll för **fotosyntesen**
- **Vakuol** som lagrar vatten

### Fotosyntes och cellandning
Fotosyntes: koldioxid + vatten + ljusenergi → socker + syre
Cellandning: socker + syre → koldioxid + vatten + energi

De två processerna är varandras motsatser och håller igång livet på jorden.',1 from ch), i1 as (insert into lessons(chapter_id,title,body,sort) select id,'DNA och arv','### DNA
**DNA** (deoxiribonukleinsyra) är molekylen som bär den genetiska informationen. Den är formad som en dubbelspiral.

- En **gen** är en bit DNA som är receptet på ett protein.
- **Kromosomer** är hoppackat DNA. Människan har **46** kromosomer (23 par) i kroppscellerna och 23 i könscellerna.

### Dominanta och recessiva anlag
Varje egenskap styrs av två anlag (ett från varje förälder).
- **Dominant** anlag (B) syns alltid.
- **Recessivt** anlag (b) syns bara om båda är recessiva (bb).

### Korsningsschema Bb × Bb
|   | B | b |
|---|---|---|
| **B** | BB | Bb |
| **b** | Bb | bb |

25 % BB, 50 % Bb, 25 % bb. Om b = blå ögon får 1 av 4 barn blå ögon.

### Mutationer
Förändringar i DNA. De flesta är harmlösa, några skadliga – och några ger fördelar som evolutionen kan bygga vidare på.',2 from ch), i2 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'biologi',id,'easy','mcq','Vilken del av cellen kallas ofta cellens kraftverk?','["Cellkärnan", "Mitokondrien", "Ribosomen", "Cellmembranet"]'::jsonb,'1'::jsonb,'I mitokondrierna sker cellandningen som frigör energi.' from ch), i3 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'biologi',id,'easy','tf','Växter utför fotosyntes.',null,'true'::jsonb,'I kloroplasterna omvandlas ljusenergi till kemisk energi i socker.' from ch), i4 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'biologi',id,'easy','fill','Vilken gas tar växterna upp från luften vid fotosyntesen?',null,'["koldioxid", "co2", "co₂"]'::jsonb,'Koldioxid + vatten + ljus → socker + syre.' from ch), i5 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'biologi',id,'easy','mcq','Vilket organ pumpar runt blodet i kroppen?','["Lungorna", "Levern", "Hjärtat", "Njurarna"]'::jsonb,'2'::jsonb,'Hjärtat är en muskel som slår ungefär 70 gånger per minut i vila.' from ch), i6 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'biologi',id,'medium','mcq','Hur många kromosomer har en vanlig mänsklig kroppscell?','["23", "46", "48", "92"]'::jsonb,'1'::jsonb,'46 kromosomer i 23 par. Könscellerna har 23.' from ch), i7 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'biologi',id,'medium','tf','Bakterier är mindre än virus.',null,'false'::jsonb,'Virus är mycket mindre än bakterier och kan inte föröka sig på egen hand.' from ch), i8 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'biologi',id,'medium','mcq','Vad kallas en organism som bryter ner döda växter och djur?','["Producent", "Konsument", "Nedbrytare", "Rovdjur"]'::jsonb,'2'::jsonb,'Nedbrytare (t.ex. svampar och bakterier) återför näringsämnen till kretsloppet.' from ch), i9 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'biologi',id,'medium','fill','Vad kallas läran om ärftlighet?',null,'["genetik", "ärftlighetslära", "genetiken"]'::jsonb,'Genetiken grundades av Gregor Mendel och hans ärtförsök.' from ch), i10 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'biologi',id,'hard','mcq','Två brunögda föräldrar bär båda anlaget Bb. Hur stor är sannolikheten att ett barn får blå ögon (bb)?','["0 %", "25 %", "50 %", "75 %"]'::jsonb,'1'::jsonb,'Korsningsschemat ger BB, Bb, Bb, bb → 1 av 4 = 25 %.' from ch), i11 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'biologi',id,'hard','match','Para ihop blodets delar med deras uppgift.','{"left": ["Röda blodkroppar", "Vita blodkroppar", "Blodplättar"], "right": ["Får blodet att levra sig", "Transporterar syre", "Bekämpar infektioner"]}'::jsonb,'[1, 2, 0]'::jsonb,'Röda = syre (hemoglobin), vita = immunförsvar, blodplättar = koagulering.' from ch), i12 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'biologi',id,'hard','tf','Vid vanlig celldelning (mitos) får dottercellerna hälften så många kromosomer som modercellen.',null,'false'::jsonb,'Vid mitos får dottercellerna lika många kromosomer. Halvering sker vid meios (bildning av könsceller).' from ch), i13 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'biologi',id,'hard','mcq','Vad menas med en art?','["Organismer som kan få fertil avkomma tillsammans", "Organismer med samma färg", "Alla djur i ett område", "Organismer som äter samma föda"]'::jsonb,'0'::jsonb,'Häst och åsna kan få mulor, men mulor är sterila – därför är häst och åsna olika arter.' from ch), i14 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'biologi',id,'expert','mcq','Varför är antibiotikaresistens ett exempel på evolution?','["Bakterier med resistensgener överlever och förökar sig", "Bakterierna lär sig undvika medicinen", "Antibiotikan muterar", "Människor blir immuna"]'::jsonb,'0'::jsonb,'Naturligt urval: de bakterier som råkar vara motståndskraftiga överlever behandlingen och för generna vidare.' from ch), i15 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'biologi',id,'expert','fill','Vilken molekyl bär cellens genetiska information?',null,'["dna", "deoxiribonukleinsyra"]'::jsonb,'DNA finns i cellkärnan och är uppbyggt av kvävebaserna A, T, C och G.' from ch), i16 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'biologi',id,'expert','mcq','I näringskedjan gräs → hare → räv: ungefär hur stor del av energin förs vidare till nästa nivå?','["100 %", "50 %", "10 %", "1 %"]'::jsonb,'2'::jsonb,'Tumregeln är att ca 10 % förs vidare – resten används till rörelse, värme och går förlorad.' from ch) insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'biologi',id,'expert','tf','Enzymer förbrukas i de reaktioner de påskyndar.',null,'false'::jsonb,'Enzymer är katalysatorer och kan användas om och om igen.' from ch;
with ch as (insert into chapters(subject_id,year,title,sort) values ('biologi',8,'Ekologi',2) returning id) insert into lessons(chapter_id,title,body,sort) select id,'Ekosystem och näringskedjor','Ett **ekosystem** är allt levande i ett område tillsammans med den icke-levande miljön (vatten, ljus, jord).

### Näringskedja
gräs → hare → räv
- **Producenter** (växter) bygger socker med fotosyntes.
- **Konsumenter** äter andra organismer (växtätare, rovdjur, toppkonsumenter).
- **Nedbrytare** (svampar, bakterier, maskar) återför näring till jorden.

### Näringsväv
I verkligheten äter djur flera olika saker – kedjorna hänger ihop i en väv. Om en art försvinner påverkas många andra.

### Energi
Bara ungefär **10 %** av energin går vidare till nästa nivå. Därför finns det många fler harar än rävar.

### Kretslopp
Kol, kväve och vatten cirkulerar mellan luft, mark och organismer. Människan påverkar kolets kretslopp genom att bränna fossila bränslen.',1 from ch;
with ch as (insert into chapters(subject_id,year,title,sort) values ('historia',8,'Revolutionernas tid',1) returning id), i0 as (insert into lessons(chapter_id,title,body,sort) select id,'Franska revolutionen','### Bakgrund (1780-talet)
Frankrike var indelat i tre **stånd**: prästerskapet, adeln och tredje ståndet (alla andra – 97 % av befolkningen). Bara tredje ståndet betalade skatt. Staten var skuldsatt efter krig, skördarna slog fel och brödpriserna steg.

### Upplysningens idéer
Tänkare som Voltaire, Rousseau och Montesquieu ifrågasatte kungens makt och talade om frihet, förnuft och folkets rätt.

### 1789
- Kungen kallar till **ständermöte**.
- Tredje ståndet bildar **Nationalförsamlingen**.
- **14 juli:** Stormningen av **Bastiljen**, ett fängelse i Paris, blir revolutionens symbol.
- Augusti: Deklarationen om människans och medborgarens rättigheter.

### Skräckväldet
1793 avrättas kung Ludvig XVI. Under Robespierre giljotineras tusentals.

### Följder
Napoleon tar makten 1799. Idéerna om **frihet, jämlikhet och broderskap** sprids över Europa.',1 from ch), i1 as (insert into lessons(chapter_id,title,body,sort) select id,'Industriella revolutionen','### Var och när?
Började i **Storbritannien** i slutet av 1700-talet och spreds till Europa och USA under 1800-talet. Sverige industrialiserades främst efter 1870.

### Varför just Storbritannien?
Kol och järn, kolonier som gav råvaror och marknader, kapital, och uppfinningar som **ångmaskinen** (James Watt) och **spinnmaskinen**.

### Vad förändrades?
- Produktion flyttade från hem och verkstäder till **fabriker**.
- **Urbanisering** – människor flyttade till städerna.
- **Järnvägar** band ihop länder.
- En ny **arbetarklass** växte fram, ofta med långa dagar, låga löner och **barnarbete**.

### Följder på sikt
Fackföreningar, arbetarrörelsen, högre levnadsstandard – men också miljöproblem och början på de utsläpp som driver dagens klimatförändring.',2 from ch), i2 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'historia',id,'easy','mcq','Vilket år bröt franska revolutionen ut?','["1689", "1789", "1848", "1914"]'::jsonb,'1'::jsonb,'Bastiljen stormades den 14 juli 1789.' from ch), i3 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'historia',id,'easy','tf','Andra världskriget slutade år 1945.',null,'true'::jsonb,'Tyskland kapitulerade i maj 1945 och Japan i september 1945.' from ch), i4 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'historia',id,'easy','mcq','Vilken svensk kung kallades ''Lejonet från Norden'' och stupade vid Lützen 1632?','["Gustav Vasa", "Gustav II Adolf", "Karl XII", "Karl XIV Johan"]'::jsonb,'1'::jsonb,'Gustav II Adolf ledde Sverige in i trettioåriga kriget.' from ch), i5 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'historia',id,'easy','fill','Vilken stad var huvudstad i Romarriket?',null,'["rom", "roma"]'::jsonb,'Enligt sägnen grundades Rom år 753 f.Kr.' from ch), i6 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'historia',id,'medium','mcq','Vad var Bastiljen?','["Ett fängelse i Paris", "Ett slott i Versailles", "En kyrka", "Ett parlament"]'::jsonb,'0'::jsonb,'Stormningen av Bastiljen den 14 juli 1789 är Frankrikes nationaldag.' from ch), i7 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'historia',id,'medium','mcq','Vilket år blev Sverige medlem i EU?','["1989", "1995", "2001", "2004"]'::jsonb,'1'::jsonb,'Efter en folkomröstning 1994 gick Sverige med den 1 januari 1995.' from ch), i8 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'historia',id,'medium','tf','Första världskriget började år 1914.',null,'true'::jsonb,'Kriget utlöstes av skotten i Sarajevo i juni 1914 och varade till 1918.' from ch), i9 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'historia',id,'medium','mcq','I vilket land började den industriella revolutionen?','["Frankrike", "Tyskland", "Storbritannien", "USA"]'::jsonb,'2'::jsonb,'Storbritannien hade kol, järn, kapital och kolonier.' from ch), i10 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'historia',id,'hard','match','Para ihop årtalet med händelsen.','{"left": ["1789", "1917", "1945", "1989"], "right": ["Berlinmurens fall", "Franska revolutionen", "Ryska revolutionen", "FN bildas"]}'::jsonb,'[1, 2, 3, 0]'::jsonb,'1789 franska revolutionen, 1917 ryska revolutionen, 1945 FN bildas, 1989 Berlinmurens fall.' from ch), i11 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'historia',id,'hard','mcq','Vad innebar det kalla kriget?','["En maktkamp mellan USA och Sovjetunionen utan direkt krig mellan dem", "Ett krig i Arktis", "Ett krig mellan Sverige och Norge", "En extremt kall vinter 1945"]'::jsonb,'0'::jsonb,'Kalla kriget pågick ca 1947–1991 med kapprustning, rymdkapplöpning och ställföreträdande krig.' from ch), i12 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'historia',id,'hard','fill','Vad kallas den ideologi som Hitler och NSDAP stod för?',null,'["nazism", "nationalsocialism", "nazismen", "nationalsocialismen"]'::jsonb,'Nationalsocialismen byggde på rasism, antisemitism och ledarkult.' from ch), i13 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'historia',id,'hard','tf','Sverige deltog med egna soldater i strid under andra världskriget.',null,'false'::jsonb,'Sverige var formellt neutralt, även om man gjorde eftergifter åt Tyskland och senare åt de allierade.' from ch), i14 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'historia',id,'expert','mcq','Vilken var en viktig orsak till franska revolutionen?','["Statsskuld och orättvis beskattning av tredje ståndet", "Pesten", "Att kolonierna blev självständiga", "Napoleons kröning"]'::jsonb,'0'::jsonb,'Frankrike var bankrutt efter krig och bara tredje ståndet betalade skatt.' from ch), i15 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'historia',id,'expert','mcq','Vad var Versaillesfreden 1919?','["Fredsavtalet efter första världskriget", "Avtalet som avslutade andra världskriget", "Frankrikes nya grundlag", "En handelsöverenskommelse"]'::jsonb,'0'::jsonb,'Tyskland fick ta på sig skulden, betala skadestånd och avstå landområden – vilket bidrog till missnöje.' from ch), i16 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'historia',id,'expert','short','Nämn en viktig följd av den industriella revolutionen.',null,'["urbanisering", "fabrik", "städer", "staden", "barnarbete", "arbetarklass", "järnväg", "miljö", "utsläpp", "fackförening", "befolkning", "ångmaskin", "löner", "massproduktion"]'::jsonb,'Exempel: urbanisering, fabriksarbete, arbetarklass, järnvägar, barnarbete, miljöpåverkan.' from ch) insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'historia',id,'expert','mcq','Vad var upplysningen?','["En idéströmning på 1700-talet som betonade förnuft, vetenskap och frihet", "En religiös väckelse på 1500-talet", "Elektrifieringen av Europa", "En konststil under renässansen"]'::jsonb,'0'::jsonb,'Upplysningens idéer låg bakom både amerikanska och franska revolutionen.' from ch;
with ch as (insert into chapters(subject_id,year,title,sort) values ('historia',9,'1900-talet',2) returning id) insert into lessons(chapter_id,title,body,sort) select id,'Världskrigen','### Första världskriget 1914–1918
**Orsaker:** nationalism, allianser, kapprustning och imperialism. **Utlösande händelse:** skotten i Sarajevo 1914.
Skyttegravskrig på västfronten. Ca 10 miljoner soldater dog. **Versaillesfreden 1919** gav Tyskland skulden.

### Mellankrigstiden
Börskrasch 1929 → depression och arbetslöshet. Missnöje banade väg för diktaturer: Mussolini i Italien, Hitler i Tyskland (1933), Stalin i Sovjetunionen.

### Andra världskriget 1939–1945
Börjar med Tysklands anfall på Polen 1 september 1939.
Viktiga vändpunkter: Stalingrad 1943, D-dagen 1944. **Förintelsen** – nazisternas folkmord på ca 6 miljoner judar samt romer, funktionsnedsatta och andra.
Kriget slutar i Europa i maj 1945 och i Asien efter atombomberna över Hiroshima och Nagasaki.

### Efter kriget
**FN** bildas 1945. **Kalla kriget** mellan USA och Sovjet delar världen fram till Berlinmurens fall 1989 och Sovjetunionens upplösning 1991.',1 from ch;
with ch as (insert into chapters(subject_id,year,title,sort) values ('geografi',7,'Kartan och världen',1) returning id), i0 as (insert into lessons(chapter_id,title,body,sort) select id,'Kartor och koordinater','### Skala
Skalan 1:50 000 betyder att 1 cm på kartan är 50 000 cm = 500 m i verkligheten.
2 cm → 1 km.

### Koordinater
- **Breddgrader (latitud)** går runt jorden parallellt med ekvatorn (0°). Nordpolen är 90° N.
- **Längdgrader (longitud/meridianer)** går från pol till pol. Nollmeridianen går genom Greenwich i London.
Stockholm ligger ungefär på 59° N, 18° Ö.

### Höjdkurvor
Linjer som binder ihop punkter på samma höjd. Täta kurvor = brant terräng.

### Olika kartor
Topografiska kartor visar terräng, tematiska kartor visar t.ex. befolkning eller klimat.',1 from ch), i1 as (insert into lessons(chapter_id,title,body,sort) select id,'Klimat och klimatzoner','### Väder och klimat
**Väder** är det som händer just nu. **Klimat** är genomsnittet över lång tid (minst 30 år).

### Klimatzoner
- **Tropisk zon** nära ekvatorn – varmt året om, regnskog eller savann.
- **Subtropisk zon** – heta somrar, t.ex. Medelhavsklimat och öknar som Sahara.
- **Tempererad zon** – fyra årstider. Här ligger större delen av Europa och Sverige.
- **Polar zon** – kallt året om, tundra och is.

### Vad påverkar klimatet?
1. **Breddgrad** – solens vinkel.
2. **Höjd över havet** – kallare högre upp.
3. **Närhet till hav** – havet jämnar ut temperaturen (maritimt klimat). Inlandet får varmare somrar och kallare vintrar (kontinentalt klimat).
4. **Havsströmmar** – Golfströmmen gör Norden mycket mildare än andra platser på samma breddgrad.',2 from ch), i2 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'geografi',id,'easy','mcq','Vilken är Norges huvudstad?','["Bergen", "Oslo", "Stockholm", "Helsingfors"]'::jsonb,'1'::jsonb,'Oslo ligger längst in i Oslofjorden.' from ch), i3 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'geografi',id,'easy','tf','Sahara är världens största varma öken.',null,'true'::jsonb,'Sahara i Nordafrika är nästan lika stor som hela USA.' from ch), i4 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'geografi',id,'easy','fill','Vilken flod rinner genom Egypten och mynnar i Medelhavet?',null,'["nilen", "nile"]'::jsonb,'Nilen är ca 6 650 km lång och räknas traditionellt som världens längsta flod.' from ch), i5 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'geografi',id,'easy','mcq','Hur många världsdelar brukar man räkna med?','["5", "6", "7", "8"]'::jsonb,'2'::jsonb,'Afrika, Antarktis, Asien, Europa, Nordamerika, Oceanien och Sydamerika.' from ch), i6 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'geografi',id,'medium','mcq','Vilket hav ligger mellan Sverige och Finland?','["Nordsjön", "Östersjön", "Atlanten", "Medelhavet"]'::jsonb,'1'::jsonb,'Östersjön är ett bräckt innanhav med låg salthalt.' from ch), i7 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'geografi',id,'medium','tf','Ekvatorn går genom Brasilien.',null,'true'::jsonb,'Ekvatorn passerar norra Brasilien, bland annat nära Amazonflodens mynning.' from ch), i8 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'geografi',id,'medium','mcq','Vad kallas linjerna på en karta som visar höjdskillnader?','["Höjdkurvor", "Breddgrader", "Meridianer", "Skala"]'::jsonb,'0'::jsonb,'Ju tätare höjdkurvor, desto brantare terräng.' from ch), i9 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'geografi',id,'medium','fill','Vilken är Sveriges största sjö?',null,'["vänern"]'::jsonb,'Vänern är också EU:s största sjö.' from ch), i10 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'geografi',id,'hard','numeric','Kartans skala är 1:50 000. Hur många kilometer i verkligheten motsvarar 2 cm på kartan?',null,'{"value": 1, "tol": 0}'::jsonb,'2 cm · 50 000 = 100 000 cm = 1 000 m = 1 km.' from ch), i11 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'geografi',id,'hard','match','Para ihop huvudstaden med landet.','{"left": ["Tokyo", "Kairo", "Lima", "Canberra"], "right": ["Australien", "Peru", "Japan", "Egypten"]}'::jsonb,'[2, 3, 1, 0]'::jsonb,'Tokyo–Japan, Kairo–Egypten, Lima–Peru, Canberra–Australien (inte Sydney!).' from ch), i12 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'geografi',id,'hard','mcq','Vad orsakar de flesta jordbävningar?','["Rörelser i jordskorpans plattor", "Starka vindar", "Månens dragningskraft", "Havsströmmar"]'::jsonb,'0'::jsonb,'Spänningar byggs upp där plattorna möts och utlöses plötsligt.' from ch), i13 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'geografi',id,'hard','tf','Golfströmmen gör klimatet i Norden varmare än det annars skulle vara.',null,'true'::jsonb,'Varmt vatten från Mexikanska golfen förs upp mot Nordatlanten.' from ch), i14 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'geografi',id,'expert','mcq','Varför har Stockholm kallare vintrar än Glasgow trots ungefär samma breddgrad?','["Stockholm har ett mer kontinentalt klimat med mindre påverkan av Atlanten", "Stockholm ligger högre över havet", "Det regnar mer i Stockholm", "Stockholm ligger närmare polcirkeln"]'::jsonb,'0'::jsonb,'Glasgow värms av Atlanten och Golfströmmen; Stockholm påverkas mer av det kalla inlandet.' from ch), i15 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'geografi',id,'expert','mcq','Vad menas med urbanisering?','["Att människor flyttar från landsbygd till städer", "Att städer blir grönare", "Att befolkningen minskar", "Att man bygger nya vägar"]'::jsonb,'0'::jsonb,'Idag bor över hälften av jordens befolkning i städer.' from ch), i16 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'geografi',id,'expert','fill','Vilken världsdel har flest invånare?',null,'["asien"]'::jsonb,'Asien har runt 4,7 miljarder invånare – ungefär 60 % av jordens befolkning.' from ch) insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'geografi',id,'expert','mcq','Vad är grundvatten?','["Vatten som finns i marken under markytan", "Vatten i sjöar", "Regnvatten", "Havsvatten"]'::jsonb,'0'::jsonb,'Grundvattnet fyller porer och sprickor i marken och är viktig dricksvattenkälla.' from ch;
with ch as (insert into chapters(subject_id,year,title,sort) values ('svenska',7,'Språkets byggstenar',1) returning id), i0 as (insert into lessons(chapter_id,title,body,sort) select id,'Ordklasser','Ord delas in i **ordklasser** efter hur de fungerar.

| Ordklass | Beskriver | Exempel |
|----------|-----------|---------|
| **Substantiv** | saker, personer, platser | hus, Lisa, glädje |
| **Verb** | vad någon gör eller vad som händer | springa, är, tänkte |
| **Adjektiv** | hur något är | röd, stor, glad |
| **Adverb** | hur, när, var något sker | snabbt, igår, här |
| **Pronomen** | ersätter substantiv | hon, den, vi, hen |
| **Prepositioner** | läge och riktning | på, under, till |
| **Konjunktioner** | binder ihop | och, men, eftersom |
| **Räkneord** | antal och ordning | tre, femte |

### Knep
- Kan du sätta *en/ett* framför? → substantiv.
- Kan du sätta *att* framför? → verb.
- Kan du böja *stor – större – störst*? → adjektiv.',1 from ch), i1 as (insert into lessons(chapter_id,title,body,sort) select id,'Satsdelar och skiljetecken','### Satsdelar
- **Subjekt** – den som gör något. *Hunden* jagar katten.
- **Predikat** – verbet, det som görs. Hunden *jagar* katten.
- **Objekt** – den som utsätts. Hunden jagar *katten*.

Fråga "Vem/vad + predikat?" för att hitta subjektet.

### Huvudsats och bisats
En **huvudsats** kan stå själv: *Vi gick hem.*
En **bisats** kan inte stå själv: *…eftersom det regnade.*

### De / dem
- **De** = subjekt (de gick hem). Testa med *vi*.
- **Dem** = objekt (jag såg dem). Testa med *oss*.

### Skiljetecken
- Punkt, frågetecken, utropstecken avslutar meningar.
- Kommatecken skiljer satser och uppräkningar.
- Direkt anföring markeras med **citattecken** eller **pratminus (–)**.',2 from ch), i2 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'svenska',id,'easy','mcq','Vilken ordklass tillhör ordet ''springa''?','["Substantiv", "Verb", "Adjektiv", "Adverb"]'::jsonb,'1'::jsonb,'Du kan sätta ''att'' framför: att springa → verb.' from ch), i3 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'svenska',id,'easy','tf','''Hus'' är ett substantiv.',null,'true'::jsonb,'Det går att säga ''ett hus'' – alltså ett substantiv.' from ch), i4 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'svenska',id,'easy','mcq','Vilket av orden är ett adjektiv?','["springer", "bil", "glad", "och"]'::jsonb,'2'::jsonb,'Glad beskriver hur någon är och kan kompareras: glad – gladare – gladast.' from ch), i5 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'svenska',id,'easy','fill','Vad kallas ordklassen som beskriver hur något är, till exempel ''röd'' och ''stor''?',null,'["adjektiv"]'::jsonb,'Adjektiv böjs efter substantivet: en röd bil, ett rött hus.' from ch), i6 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'svenska',id,'medium','mcq','Vilken mening är korrekt skriven?','["Dom gick hem.", "De gick hem.", "Dem gick hem.", "Di gick hem."]'::jsonb,'1'::jsonb,'''De'' är subjekt i meningen (jämför: vi gick hem).' from ch), i7 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'svenska',id,'medium','tf','En synonym är ett ord med motsatt betydelse.',null,'false'::jsonb,'Synonymer betyder ungefär samma sak (glad – lycklig). Motsatsord kallas antonymer.' from ch), i8 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'svenska',id,'medium','mcq','Vad är subjekt i meningen ''Hunden jagar katten''?','["Hunden", "jagar", "katten", "Det finns inget subjekt"]'::jsonb,'0'::jsonb,'Vem jagar? Hunden. Subjektet är den som utför handlingen.' from ch), i9 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'svenska',id,'medium','fill','Vad kallas ord med motsatt betydelse, till exempel varm – kall?',null,'["antonym", "antonymer", "motsatsord"]'::jsonb,'Antonym kommer från grekiskans *anti* (mot) och *onyma* (namn).' from ch), i10 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'svenska',id,'hard','mcq','Vilket skiljetecken används för att visa direkt anföring (att någon säger något)?','["Citattecken eller pratminus", "Semikolon", "Kolon", "Parentes"]'::jsonb,'0'::jsonb,'– Hej, sa hon. Eller: "Hej", sa hon.' from ch), i11 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'svenska',id,'hard','match','Para ihop stilfiguren med exemplet.','{"left": ["Metafor", "Liknelse", "Besjälning", "Ironi"], "right": ["Säger motsatsen till vad man menar", "Hon är en klippa", "Vinden viskade", "Stark som en björn"]}'::jsonb,'[1, 3, 2, 0]'::jsonb,'Metafor = bildligt utan ''som'', liknelse = med ''som'', besjälning = ger döda ting liv, ironi = motsatsen.' from ch), i12 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'svenska',id,'hard','tf','''Hen'' är ett könsneutralt pronomen som finns med i Svenska Akademiens ordlista.',null,'true'::jsonb,'Hen togs med i SAOL 2015.' from ch), i13 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'svenska',id,'hard','mcq','Vilken av följande är en bisats?','["eftersom det regnade", "Det regnade.", "Regnet öste ner.", "Vi gick hem."]'::jsonb,'0'::jsonb,'En bisats kan inte stå ensam och inleds ofta med ord som eftersom, att, som, när.' from ch), i14 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'svenska',id,'expert','mcq','Vad kännetecknar en argumenterande text?','["Tes, argument och motargument", "Rim och vers", "Dialog och scenanvisningar", "En kronologisk berättelse"]'::jsonb,'0'::jsonb,'Du tar ställning (tes), ger skäl (argument) och bemöter invändningar (motargument).' from ch), i15 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'svenska',id,'expert','mcq','En flicka har brunt hår. Vilket alternativ är rätt skrivet?','["en brun hårig flicka", "en brunhårig flicka", "en brun-hårig flicka", "en brunthårig flicka"]'::jsonb,'1'::jsonb,'Sammansatta ord skrivs ihop. ''Brun hårig'' skulle betyda en hårig flicka som är brun.' from ch), i16 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'svenska',id,'expert','short','Förklara kort skillnaden mellan ''de'' och ''dem''.',null,'["subjekt", "objekt", "vi", "oss", "den som gör", "utsätts"]'::jsonb,'De är subjektsform (de gick = vi gick), dem är objektsform (jag såg dem = jag såg oss).' from ch) insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'svenska',id,'expert','fill','Vilken svensk författare skrev romanen ''Röda rummet'' (1879)?',null,'["strindberg", "august strindberg"]'::jsonb,'Röda rummet brukar kallas den första moderna svenska romanen.' from ch;
with ch as (insert into chapters(subject_id,year,title,sort) values ('engelska',7,'Grammar',1) returning id), i0 as (insert into lessons(chapter_id,title,body,sort) select id,'Tenses – verbens tidsformer','### Present simple
Vanor och fakta. *She **plays** tennis on Mondays.* Lägg till **-s** i tredje person singular (he/she/it).
Negation: *He **doesn''t** like tea.* (inte "don''t" i tredje person)

### Present continuous
Pågår just nu. *I **am reading**.* (am/is/are + -ing)

### Past simple
Avslutat förr. *They **went** home.* Regelbundna verb får **-ed**: *walked*. Oregelbundna måste läras in: go → went, eat → ate, see → saw.

### Present perfect
Har hänt, med koppling till nu. *I **have seen** that film.* (have/has + perfekt particip: seen, eaten, gone)

### Future
*I **will** call you.* / *I **am going to** study.*

### Conditional (if-satser)
*If I **were** rich, I **would** travel.* I formell engelska används *were* för alla personer i overkliga villkor. *Was* hörs i vardagligt tal.',1 from ch), i1 as (insert into lessons(chapter_id,title,body,sort) select id,'Irregular verbs','De vanligaste oregelbundna verben – lär dig dem i tre former:

| Infinitiv | Past simple | Past participle | Svenska |
|-----------|-------------|-----------------|---------|
| be | was/were | been | vara |
| go | went | gone | gå |
| eat | ate | eaten | äta |
| see | saw | seen | se |
| take | took | taken | ta |
| write | wrote | written | skriva |
| speak | spoke | spoken | tala |
| come | came | come | komma |
| run | ran | run | springa |
| buy | bought | bought | köpa |
| think | thought | thought | tänka |
| know | knew | known | veta |

### Oregelbundna plural
child → **children**, man → **men**, woman → **women**, foot → **feet**, tooth → **teeth**, mouse → **mice**.',2 from ch), i2 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'engelska',id,'easy','mcq','What is ''hund'' in English?','["cat", "dog", "horse", "bird"]'::jsonb,'1'::jsonb,'Hund = dog.' from ch), i3 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'engelska',id,'easy','tf','''I am'' is correct English.',null,'true'::jsonb,'I am, you are, he/she/it is, we are, they are.' from ch), i4 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'engelska',id,'easy','fill','Translate to English: ''tack''',null,'["thanks", "thank you", "thankyou"]'::jsonb,'Thanks / thank you.' from ch), i5 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'engelska',id,'easy','mcq','Choose the correct form: ''She ___ a student.''','["am", "is", "are", "be"]'::jsonb,'1'::jsonb,'Third person singular (he/she/it) takes ''is''.' from ch), i6 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'engelska',id,'medium','mcq','What is the past tense of ''go''?','["goed", "went", "gone", "going"]'::jsonb,'1'::jsonb,'Go – went – gone. ''Gone'' is the past participle.' from ch), i7 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'engelska',id,'medium','tf','''Childs'' is the plural of ''child''.',null,'false'::jsonb,'The plural is ''children''.' from ch), i8 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'engelska',id,'medium','fill','What is the past tense of ''eat''?',null,'["ate"]'::jsonb,'Eat – ate – eaten.' from ch), i9 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'engelska',id,'medium','mcq','Which sentence is correct?','["He don''t like tea.", "He doesn''t like tea.", "He not like tea.", "He doesn''t likes tea."]'::jsonb,'1'::jsonb,'Third person singular uses ''doesn''t'' + base form of the verb.' from ch), i10 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'engelska',id,'hard','mcq','Choose the most formal/correct option: ''If I ___ rich, I would travel the world.''','["am", "was", "were", "be"]'::jsonb,'2'::jsonb,'Unreal conditionals use ''were'' for all persons in formal English. ''Was'' is common in speech.' from ch), i11 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'engelska',id,'hard','match','Match each word with its synonym.','{"left": ["big", "happy", "fast", "cold"], "right": ["quick", "large", "chilly", "glad"]}'::jsonb,'[1, 3, 0, 2]'::jsonb,'big–large, happy–glad, fast–quick, cold–chilly.' from ch), i12 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'engelska',id,'hard','fill','Complete with the past participle: ''I have ___ that film.'' (see)',null,'["seen"]'::jsonb,'See – saw – seen. Present perfect = have/has + past participle.' from ch), i13 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'engelska',id,'hard','tf','''Their'', ''there'' and ''they''re'' mean the same thing.',null,'false'::jsonb,'Their = deras, there = där, they''re = they are. They sound the same but mean different things.' from ch), i14 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'engelska',id,'expert','mcq','Which word is a synonym of ''reluctant''?','["eager", "unwilling", "careful", "tired"]'::jsonb,'1'::jsonb,'Reluctant = unwilling, hesitant. Eager is the opposite.' from ch), i15 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'engelska',id,'expert','mcq','Which sentence is in the passive voice?','["The cake was eaten by Tom.", "Tom ate the cake.", "Tom is eating cake.", "Tom will eat cake."]'::jsonb,'0'::jsonb,'Passive: be + past participle. The subject (the cake) receives the action.' from ch), i16 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'engelska',id,'expert','short','Explain the difference between ''fewer'' and ''less''.',null,'["count", "uncount", "räknebar", "oräknebar", "plural", "number", "amount", "mängd", "antal"]'::jsonb,'''Fewer'' is used with countable nouns (fewer cars), ''less'' with uncountable nouns (less water).' from ch) insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'engelska',id,'expert','fill','Complete the idiom: ''It''s raining cats and ___.''',null,'["dogs"]'::jsonb,'It means it is raining very heavily.' from ch;
with ch as (insert into chapters(subject_id,year,title,sort) values ('spanska',7,'Grunderna',1) returning id), i0 as (insert into lessons(chapter_id,title,body,sort) select id,'Hälsningsfraser','### Hälsa och ta farväl
- **Hola** – hej
- **Buenos días** – god morgon
- **Buenas tardes** – god eftermiddag
- **Buenas noches** – god kväll / god natt
- **Adiós** / **Hasta luego** – hejdå / vi ses

### Artighet
- **Gracias** – tack · **De nada** – varsågod
- **Por favor** – snälla/tack (vid förfrågan)
- **Perdón** – ursäkta

### Presentera dig
- **Me llamo Ana.** – Jag heter Ana.
- **¿Cómo te llamas?** – Vad heter du?
- **¿Cuántos años tienes?** – Hur gammal är du? (ordagrant: hur många år har du)
- **Tengo trece años.** – Jag är tretton år.
- **Soy de Suecia.** – Jag är från Sverige.

### Räkneord 1–10
uno, dos, tres, cuatro, cinco, seis, siete, ocho, nueve, diez',1 from ch), i1 as (insert into lessons(chapter_id,title,body,sort) select id,'Verb i presens','Spanska verb slutar på **-ar**, **-er** eller **-ir**. Ändelsen visar vem som gör något – därför behövs oftast inget pronomen.

### hablar (tala) – -ar
| | |
|---|---|
| yo | habl**o** |
| tú | habl**as** |
| él/ella | habl**a** |
| nosotros | habl**amos** |
| vosotros | habl**áis** |
| ellos/ellas | habl**an** |

### vivir (bo) – -ir
viv**o**, viv**es**, viv**e**, viv**imos**, viv**ís**, viv**en**

### ser och estar – två sätt att säga "vara"
- **ser** = permanenta egenskaper, ursprung, yrke. *Soy sueco.* *Ella es alta.*
- **estar** = tillfälliga tillstånd och plats. *Estoy cansado.* *Madrid está en España.*

### gustar
*Me gusta el libro* (jag gillar boken) men *me gusta**n** los libros* – verbet böjs efter det man gillar, som är subjekt i satsen.',2 from ch), i2 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'spanska',id,'easy','mcq','Vad betyder ''hola''?','["hej", "hejdå", "tack", "ja"]'::jsonb,'0'::jsonb,'Hola är den vanligaste hälsningen.' from ch), i3 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'spanska',id,'easy','tf','''Gracias'' betyder tack.',null,'true'::jsonb,'Svaret på gracias är ofta ''de nada'' – varsågod.' from ch), i4 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'spanska',id,'easy','fill','Vad heter ''vatten'' på spanska?',null,'["agua", "el agua"]'::jsonb,'Agua är femininum men får artikeln *el* i singular eftersom ordet börjar på betonat a.' from ch), i5 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'spanska',id,'easy','mcq','Vilket är räkneordet för 3?','["dos", "tres", "cuatro", "cinco"]'::jsonb,'1'::jsonb,'uno, dos, tres, cuatro, cinco…' from ch), i6 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'spanska',id,'medium','mcq','''Yo ___ español.'' (hablar)','["hablo", "hablas", "habla", "hablamos"]'::jsonb,'0'::jsonb,'Första person singular av -ar-verb slutar på -o.' from ch), i7 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'spanska',id,'medium','tf','''Buenas noches'' betyder god morgon.',null,'false'::jsonb,'Buenas noches = god kväll/god natt. God morgon = buenos días.' from ch), i8 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'spanska',id,'medium','fill','Vad heter ''röd'' på spanska (maskulin form)?',null,'["rojo"]'::jsonb,'Rojo (mask.), roja (fem.).' from ch), i9 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'spanska',id,'medium','mcq','Vilken artikel passar: ''___ casa''','["el", "la", "los", "un"]'::jsonb,'1'::jsonb,'Casa är femininum singular → la casa.' from ch), i10 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'spanska',id,'hard','match','Para ihop veckodagarna.','{"left": ["lunes", "miércoles", "viernes", "domingo"], "right": ["fredag", "söndag", "måndag", "onsdag"]}'::jsonb,'[2, 3, 0, 1]'::jsonb,'lunes=måndag, martes=tisdag, miércoles=onsdag, jueves=torsdag, viernes=fredag, sábado=lördag, domingo=söndag.' from ch), i11 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'spanska',id,'hard','mcq','''Nosotros ___ en Madrid.'' (vivir)','["vivo", "vives", "vive", "vivimos"]'::jsonb,'3'::jsonb,'Nosotros-formen av -ir-verb slutar på -imos.' from ch), i12 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'spanska',id,'hard','fill','Vad betyder ''¿Cuántos años tienes?''',null,'["hur gammal", "hur många år"]'::jsonb,'Ordagrant ''hur många år har du'' – spanskan använder tener (ha) för ålder.' from ch), i13 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'spanska',id,'hard','tf','Spanska adjektiv står oftast efter substantivet.',null,'true'::jsonb,'Un coche rojo – en röd bil.' from ch), i14 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'spanska',id,'expert','mcq','''Ella ___ cansada.'' Välj rätt form av ser/estar.','["es", "está", "son", "están"]'::jsonb,'1'::jsonb,'Trötthet är ett tillfälligt tillstånd → estar.' from ch), i15 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'spanska',id,'expert','mcq','Preteritum: ''Ayer yo ___ al cine.'' (ir)','["voy", "fui", "iba", "iré"]'::jsonb,'1'::jsonb,'Fui är preteritum av både ir och ser. Ayer (igår) signalerar avslutad dåtid.' from ch), i16 as (insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'spanska',id,'expert','fill','Vad är plural av ''el lápiz'' (pennan)?',null,'["los lápices", "lápices", "los lapices", "lapices"]'::jsonb,'Ord på -z byter till -ces i plural.' from ch) insert into questions(subject_id,chapter_id,difficulty,qtype,prompt,options,answer,explanation) select 'spanska',id,'expert','mcq','''Me gustan los libros'' – varför heter det ''gustan'' och inte ''gusta''?','["För att ''los libros'' är plural och fungerar som subjekt", "För att ''me'' är plural", "För att det är dåtid", "För att det är artigare"]'::jsonb,'0'::jsonb,'Gustar böjs efter det som gillas: me gusta el libro, me gustan los libros.' from ch;
